export function stageWorld(code: string): number {
  return Number(code.split('-')[0])
}

export const SOLID_EMPTY = 0
export const SOLID_GROUND = 1
export const SOLID_BLOCK = 2
export const SOLID_LEDGE = 3
export const SOLID_GATE = 4
export const SOLID_PIPE = 5
export const SOLID_CRATE = 6
export const SOLID_WATER = 7
export const SOLID_BELT_LEFT = 8
export const SOLID_BELT_RIGHT = 9
export const SOLID_BRIDGE = 10

export type SpawnKind =
  | 'token'
  | 'pumpbug'
  | 'rivet-roller'
  | 'steam-vent'
  | 'springstep'
  | 'piston'
  | 'lift'
  | 'checkpoint'
  | 'goal'
